## Live-State Workflow
```
// Live-state workflow: preflight + WS open + close-code backoff
// Requires: npm i ws
import WebSocket from 'ws';

const API_KEY = process.env.TIKTOOL_API_KEY;
const BASE = 'https://api.tik.tools';
const WS_BASE = 'wss://api.tik.tools';
const WATCHLIST = ['creator1', 'creator2', 'creator3'];
const WS_BUDGET = 100;
const STREAM_END = new Set([4005, 4006, 4555]);

const live = new Map();      // uniqueId -> WebSocket
const cooldown = new Map();  // uniqueId -> retryAt (ms epoch)
const fails = new Map();     // uniqueId -> consecutive 4404 count

// Returns { uniqueId: is_live } map built from the array response.
async function preflight(ids) {
  if (!ids.length) return {};
  const r = await fetch(`${BASE}/webcast/bulk_live_check?apiKey=${API_KEY}`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ unique_ids: ids }),
  });
  const { data = [] } = await r.json();
  return Object.fromEntries(data.map(row => [row.unique_id, !!row.is_live]));
}

function backoffFor(code, n) {
  if (code === 4404) return [, , ][Math.min(n, 2)] ?? (5 + Math.min(n - 3, 5) * 5) * ;
  if (STREAM_END.has(code)) return ;
  if (code === 4429) return ;
  return ;
}

function openWs(uniqueId) {
  if (live.has(uniqueId)) return;
  const ws = new WebSocket(`${WS_BASE}?apiKey=${API_KEY}&uniqueId=${encodeURIComponent(uniqueId)}`);
  live.set(uniqueId, ws);
  ws.on('message', raw => {
    const ev = JSON.parse(raw.toString());
    if (ev.event === 'roomInfo') return;
    console.log(uniqueId, ev.event);
  });
  ws.on('close', (code) => {
    live.delete(uniqueId);
    const n = code === 4404 ? (fails.get(uniqueId) || 0) + 1 : 0;
    fails.set(uniqueId, n);
    cooldown.set(uniqueId, Date.now() + backoffFor(code, n));
  });
  ws.on('error', () => {});
}

async function tick() {
  if (live.size >= WS_BUDGET * 0.9) return;
  const now = Date.now();
  const due = WATCHLIST.filter(u => !live.has(u) && (cooldown.get(u) || 0) <= now);
  const status = await preflight(due);
  for (const [u, isLive] of Object.entries(status)) {
    if (isLive) { fails.delete(u); openWs(u); }
    else cooldown.set(u, now + );
  }
}

setInterval(tick, ); tick();
```

## WebSocket Events
### Chat-only and gift-only feeds
```
Write a minimal one-file program that streams ONLY TikTok LIVE chat messages using the Tik.Tools API. Steps:

1. GET https://api.tik.tools/api/live/top-channels (no auth, public) -> channels[0].uniqueId.
2. POST https://api.tik.tools/authentication/jwt?apiKey=your_api_key body {"allowed_creators":["<user>"],"expire_after":600,"max_websockets":1} -> {data:{token}}.
3. Open WS wss://api.tik.tools?uniqueId=<user>&jwtKey=<token>.
4. Each message: {event, data:{user:{nickname,uniqueId}, comment}}. Filter event === 'chat' only.
5. Render: "<nickname>: <comment>".

One file. Demo key your_api_key = public, 10-min sessions, 1 concurrent WS. Upgrade free at https://tik.tools.
```

```
Write a minimal one-file program that streams ONLY TikTok LIVE gift events using the Tik.Tools API + WebSocket. Steps:

1. GET https://api.tik.tools/api/live/top-channels (no auth, public) -> pick channels[0].uniqueId.
2. POST https://api.tik.tools/authentication/jwt?apiKey=your_api_key body {"allowed_creators":["<user>"],"expire_after":600,"max_websockets":1} -> {data:{token}}.
3. Open WS wss://api.tik.tools?uniqueId=<user>&jwtKey=<token>.
4. Each message is JSON {event, data:{user:{nickname,uniqueId}, giftName, repeatCount, diamondCount}}. Filter event === 'gift' only.
5. Render: "<sender> sent <giftName> x<repeatCount> (+<diamondCount*repeatCount> diamonds)".

One file, zero deps (Python: pip install websockets). Comment the swap-the-key line. Demo key your_api_key = public, 10-min sessions, 1 concurrent WS. Upgrade free at https://tik.tools.
```

